//! The 2024 Ruleset (ADR-0008): its Content ID prefix, its economy and its encodings.
//!
//! The public seam is [`Rules2024`], an implementation of [`Ruleset`]. Its encodings are
//! the RON files under `data/rules-2024/`, embedded at build time (ADR-0035); the
//! directory is empty until real encodings start (build-order step 6). There are no hooks
//! yet (ADR-0036).

use mm_core::{ActionEconomy, Refresh, ResourceDecl, Ruleset, Source, SourceRole, Sources};

/// The 2024 rules.
#[derive(Debug, Clone, Copy)]
pub struct Rules2024;

/// `(name, text)` for each embedded encoding, generated by `build.rs`.
const ENCODINGS: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/encodings.rs"));

impl Ruleset for Rules2024 {
    const PREFIX: &'static str = "2024";

    fn resources() -> Vec<ResourceDecl> {
        vec![ResourceDecl {
            name: "spell-slot",
            // In our words: a creature spends at most one spell slot on its own turn.
            spend_cap_per_turn: 1,
            ordered: true,
            refresh: Refresh::LongRest,
        }]
    }

    fn actions() -> ActionEconomy {
        ActionEconomy {
            bonus_action: true,
            reaction: true,
        }
    }

    fn encodings() -> Sources {
        Sources {
            files: ENCODINGS
                .iter()
                .map(|&(name, text)| Source {
                    name: format!("rules-2024/{name}"),
                    role: SourceRole::Encoding,
                    text: text.to_owned(),
                })
                .collect(),
        }
    }
}
